from pathlib import Path
import re
p=Path('client/src/App.jsx'); a=p.read_text()

anchor='function AssignmentPanel({ caseId, item, onChanged }) {'
if 'function ProFeatureCard(' not in a:
 block=r'''function ProFeatureCard({title,text,onUpgrade}){return <section className="contentCard proFeatureCard"><div><span>PRIVAT PRO</span><h3>{title}</h3><p>{text}</p></div><button className="primaryButton" onClick={onUpgrade}>Pro ansehen · 4,99 €</button></section>}

function OnboardingFlow({user,onDone}){
 const [step,setStep]=useState(0);const [useCase,setUseCase]=useState(user.onboardingUseCase||'private');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
 async function finish(){setBusy(true);setError('');try{const r=await api('/api/onboarding',{method:'PATCH',body:JSON.stringify({useCase})});onDone(r.user,useCase)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <div className="onboardingBackdrop"><div className="onboardingCard"><div className="onboardingProgress">{[0,1,2,3].map(x=><i key={x} className={x<=step?'active':''}/>)}</div>{step===0&&<div className="onboardingStep"><span>WILLKOMMEN BEI MÄNGELFIX</span><h1>Ein Mangel. Ein sauberer Vorgang.</h1><p>MängelFix ist nicht nur für Mietwohnungen da. Dokumentiere genauso beschädigte Lieferungen, fehlerhafte Produkte, Werkstattleistungen, Reisemängel oder Dienstleistungen.</p><div className="onboardingExamples"><b>Lieferung</b><b>Produkt</b><b>Wohnen</b><b>Werkstatt</b><b>Reise</b><b>Dienstleistung</b></div></div>}{step===1&&<div className="onboardingStep"><span>DEIN ARBEITSBEREICH</span><h1>Wie möchtest du MängelFix nutzen?</h1><div className="onboardingChoice"><button className={useCase==='private'?'selected':''} onClick={()=>setUseCase('private')}><strong>Privat</strong><p>Eigene Mängel dokumentieren und selbst an Händler, Vermieter, Werkstatt oder andere Empfänger senden.</p><small>Die Gegenseite braucht kein MängelFix-Konto.</small></button><button className={useCase==='management'?'selected':''} onClick={()=>setUseCase('management')}><strong>Hausverwaltung</strong><p>Objekte, Einheiten, Mieter, Zuständigkeiten, Termine und Dienstleister gemeinsam im Team verwalten.</p><small>14 Tage kostenlos testen.</small></button></div></div>}{step===2&&<div className="onboardingStep"><span>SO LÄUFT EIN VORGANG</span><h1>Von der Feststellung bis zur Erledigung.</h1><div className="onboardingWorkflow"><div><b>1</b><span><strong>Mangel erfassen</strong><small>Passende Felder und Kategorien je nach Fallart.</small></span></div><div><b>2</b><span><strong>Beweise sichern</strong><small>Fotos und mit Pro auch PDFs, Rechnungen und Vorher/Nachher.</small></span></div><div><b>3</b><span><strong>Dokument erstellen</strong><small>Eine nachvollziehbare PDF aus deinen Angaben.</small></span></div><div><b>4</b><span><strong>Nachhalten</strong><small>Mit Pro: Fristen, Aufgaben, Termine, Archiv und Auswertungen.</small></span></div></div></div>}{step===3&&<div className="onboardingStep ready"><span>BEREIT</span><h1>{useCase==='management'?'Richte jetzt deine Verwaltung ein.':'Dein erster Mangel kann kommen.'}</h1><p>{useCase==='management'?'Nach der Einführung öffnet sich die Verwaltungseinrichtung. Es wird noch nichts kostenpflichtig abgeschlossen.':'Privat Free kannst du dauerhaft verwenden. Pro kannst du jederzeit später aktivieren.'}</p><div className="onboardingPlan"><strong>{useCase==='management'?'14 Tage kostenlos':'Privat Free'}</strong><span>{useCase==='management'?'danach Tarif nach Einheiten':'bis 5 aktive Vorgänge · 3 Fotos je Vorgang'}</span></div></div>}{error&&<div className="errorBox">{error}</div>}<div className="onboardingActions"><button className="secondaryButton" disabled={busy||step===0} onClick={()=>setStep(Math.max(0,step-1))}>Zurück</button><span>{step+1} / 4</span>{step<3?<button className="primaryButton" onClick={()=>setStep(step+1)}>Weiter →</button>:<button className="primaryButton" disabled={busy} onClick={finish}>{busy?'Speichern…':useCase==='management'?'Verwaltung einrichten →':'MängelFix starten →'}</button>}</div></div></div>
}

'''
 a=a.replace(anchor,block+anchor,1)

# New case Free/Pro awareness
a=a.replace('function NewCase({ onClose, onCreated }) {','function NewCase({ onClose, onCreated, pro=true, entitlements=null }) {',1)
old='<label>Rückmeldung / Frist bis<input type="date" value={form.deadlineOn} onChange={e => field(\'deadlineOn\', e.target.value)} /></label>'
new='<label className={!pro?\'proLockedField\':\'\'}>Rückmeldung / Frist bis {!pro&&<span className="fieldProTag">PRO</span>}<input disabled={!pro} type="date" value={form.deadlineOn} onChange={e => field(\'deadlineOn\', e.target.value)} /></label>'
a=a.replace(old,new,1)
if 'freeCaseHint' not in a:
 a=a.replace('<form onSubmit={submit} className="caseForm">','<form onSubmit={submit} className="caseForm">{!pro&&<div className="freeCaseHint"><b>Privat Free</b><span>{entitlements?.usage?.activeCases||0} / 5 aktive Vorgänge · Fristen und erweiterte Organisation mit Pro.</span></div>}',1)

# Detail feature gates
a=a.replace('function CaseDetail({ caseId, onBack, onUpdated, user, onProfile }) {','function CaseDetail({ caseId, onBack, onUpdated, user, onProfile, pro=true, onUpgrade }) {',1)
a=a.replace('  const item = data.case;\n','  const item = data.case;\n  const tenantLinked=Boolean(item.submitted_by_tenant && data.viewerRole!==\'management\');\n',1)
old_panels='<AssignmentPanel caseId={caseId} item={item} onChanged={async()=>{await load();onUpdated();}} /><CaseCalendarPanel caseId={caseId}/><CaseTasksPanel caseId={caseId}/>'
new_panels='<AssignmentPanel caseId={caseId} item={item} onChanged={async()=>{await load();onUpdated();}} />{data.viewerRole===\'management\'||pro||tenantLinked?<CaseCalendarPanel caseId={caseId} readOnly={data.viewerRole!==\'management\'&&(tenantLinked||!pro)}/>:<ProFeatureCard title="Kalender & Termine" text="Plane Termine und Erinnerungen direkt am Vorgang." onUpgrade={onUpgrade}/>} {data.viewerRole===\'management\'||(pro&&!tenantLinked)?<CaseTasksPanel caseId={caseId}/>:(!tenantLinked?<ProFeatureCard title="Aufgaben & Wiedervorlagen" text="Halte nächste Schritte, Fälligkeiten und Erinnerungen strukturiert fest." onUpgrade={onUpgrade}/>:null)}'
if old_panels not in a: raise SystemExit('case panel anchor missing')
a=a.replace(old_panels,new_panels,1)
old_ev='''<label className="secondaryButton uploadButton">Belege hinzufügen<input type="file" accept="image/*,application/pdf" multiple onChange={async e=>{const fd=new FormData();[...e.target.files].forEach(f=>fd.append('files',f));try{await api(`/api/cases/${caseId}/evidence`,{method:'POST',body:fd});await load();onUpdated()}catch(err){setError(err.message)}e.target.value=''}} /></label>'''
new_ev='''{pro||data.viewerRole==='management'?<label className="secondaryButton uploadButton">Belege hinzufügen<input type="file" accept="image/*,application/pdf" multiple onChange={async e=>{const fd=new FormData();[...e.target.files].forEach(f=>fd.append('files',f));try{await api(`/api/cases/${caseId}/evidence`,{method:'POST',body:fd});await load();onUpdated()}catch(err){setError(err.message)}e.target.value=''}} /></label>:<label className="secondaryButton uploadButton">Fotos hinzufügen · max. 3<input type="file" accept="image/*" multiple onChange={uploadImages}/></label>}'''
a=a.replace(old_ev,new_ev,1)
a=a.replace('Vorher/Nachher-Fotos, Rechnungen, Lieferscheine oder PDF-Dokumente direkt am Vorgang.','{pro||data.viewerRole===\'management\'?\'Vorher/Nachher-Fotos, Rechnungen, Lieferscheine oder PDF-Dokumente direkt am Vorgang.\':\'Privat Free: bis zu 3 normale Fotos. Dokumente und erweiterte Belegtypen gibt es mit Pro.\'}',1)

# read-only shared appointments for connected tenants
a=a.replace('function CaseCalendarPanel({caseId}){','function CaseCalendarPanel({caseId,readOnly=false}){',1)
a=a.replace('<button className="secondaryButton" onClick={()=>setOpen(!open)}>{open?\'Schließen\':\'+ Termin\'}</button></div>{error&&',"{!readOnly&&<button className=\"secondaryButton\" onClick={()=>setOpen(!open)}>{open?'Schließen':'+ Termin'}</button>}</div>{error&&",1)
a=a.replace('{open&&<form className="calendarCreate"','{!readOnly&&open&&<form className="calendarCreate"',1)
a=a.replace("{ev.readonly?<strong>{ev.status==='scheduled'?'BESTÄTIGT':'HANDWERKER'}</strong>:<select","{ev.readonly||readOnly?<strong>{ev.event_type==='contractor'?(ev.status==='scheduled'?'BESTÄTIGT':'HANDWERKER'):'GETEILT'}</strong>:<select",1)

# modern billing plan picker
pat=r"function BillingView\(\)\{.*?\n\}\n\nfunction AccountSecurityView"
new_billing=r'''function BillingView(){
 const [data,setData]=useState(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [cycle,setCycle]=useState('monthly');useEffect(()=>{api('/api/billing/plan').then(setData).catch(e=>setError(e.message))},[]);
 async function checkout(planCode){setBusy(true);setError('');try{const r=await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({cycle,planCode})});if(r?.url)window.location.href=r.url}catch(e){setError(e.message)}finally{setBusy(false)}}async function portal(){setBusy(true);setError('');try{const r=await api('/api/billing/portal',{method:'POST'});if(r?.url)window.location.href=r.url}catch(e){setError(e.message)}finally{setBusy(false)}}
 if(!data)return <div className="workspacePage"><div className="emptyCard">Tarif wird geladen…</div></div>;const org=data.scope==='organization',p=data.plan,trial=p.subscription_status==='trialing',days=p.trial_ends_at?Math.max(0,Math.ceil((new Date(p.trial_ends_at)-new Date())/86400000)):null,plans=data.catalog||[];const price=x=>cycle==='yearly'?x.yearly:x.monthly;
 return <div className="workspacePage billingPage"><div className="workspaceHeading"><div><span>TARIF & ABRECHNUNG</span><h1>{org?'MängelFix Verwaltung':'MängelFix Privat'}</h1><p>{org?'Tarif nach verwalteten Einheiten wählen.':'Free dauerhaft nutzen oder für 4,99 € auf Privat Pro erweitern.'}</p></div><div className="billingCycle"><button className={cycle==='monthly'?'active':''} onClick={()=>setCycle('monthly')}>Monatlich</button><button className={cycle==='yearly'?'active':''} onClick={()=>setCycle('yearly')}>Jährlich · günstiger</button></div></div>{error&&<div className="errorBox">{error}</div>}<section className="workspacePanel billingHero"><div><span>AKTUELLER STATUS</span><h2>{trial?`Testphase · noch ${days} Tag${days===1?'':'e'}`:(p.plan_code||'private_free').replaceAll('_',' ')}</h2><p>{org?'Eine Einheit ist eine separat verwaltete Wohnung oder Gewerbeeinheit.':'Deine privaten Vorgänge funktionieren unabhängig davon, ob eine Hausverwaltung MängelFix verwendet.'}</p></div>{p.subscription_customer_id&&<button className="secondaryButton" disabled={busy} onClick={portal}>Abo verwalten</button>}</section>{org&&data.usage&&<div className="billingUsage"><article><span>TEAMMITGLIEDER</span><b>{data.usage.members} / {p.max_members}</b></article><article><span>OBJEKTE</span><b>{data.usage.properties} / {p.max_properties}</b></article><article><span>EINHEITEN</span><b>{data.usage.units} / {p.max_units}</b></article></div>}<div className={`billingPlanGrid ${org?'managementPlans':'privatePlans'}`}>{plans.map(plan=>{const free=price(plan)===0,configured=Boolean(data.checkoutConfigured&&plan.checkout?.[cycle]),current=p.plan_code===plan.code;return <article className={`billingPlanCard ${plan.code.includes('_pro')?'featured':''} ${current?'current':''}`} key={plan.code}><span>{current?'AKTUELLER TARIF':plan.scope==='private'?'PRIVAT':'VERWALTUNG'}</span><h2>{plan.name}</h2><div className="billingBigPrice"><b>{price(plan).toLocaleString('de-DE',{minimumFractionDigits:free?0:2})} €</b><small>{free?'dauerhaft kostenlos':cycle==='yearly'?'/ Jahr':'/ Monat'}</small></div>{plan.maxUnits&&<p><b>Bis {plan.maxUnits} Einheiten</b> · {plan.maxMembers} Mitarbeiter</p>}<ul>{plan.code==='private_free'?<><li>Bis 5 aktive Vorgänge</li><li>Bis 3 Fotos je Vorgang</li><li>Basis-PDF & Verlauf</li><li>Manuelle Empfänger</li></>:plan.code==='private_pro'?<><li>Unbegrenzte aktive Vorgänge</li><li>Erweiterte Fotos, PDFs & Belege</li><li>Fristen, Aufgaben & Kalender</li><li>Archiv, Analysen & Übergabeprotokolle</li></>:<><li>Alle Mängelmanagement-Funktionen</li><li>Team, Mieter & Dienstleister</li><li>Kalender, Aufgaben & Auswertungen</li><li>14 Tage kostenlos testen</li></>}</ul>{free?<button className="secondaryButton" disabled>Im Konto enthalten</button>:current?<button className="secondaryButton" disabled>Aktiv</button>:configured?<button className="primaryButton" disabled={busy} onClick={()=>checkout(plan.code)}>{busy?'Einen Moment…':cycle==='yearly'?'Jahrestarif wählen':'Monatstarif wählen'}</button>:<button className="primaryButton" disabled>Zahlung wird beim Server-Setup aktiviert</button>}</article>})}</div></div>;
}

function AccountSecurityView'''
a,n=re.subn(pat,new_billing,a,count=1,flags=re.S)
if n!=1:raise SystemExit('billing replacement failed')

# Workspace entitlements/onboarding
a=a.replace("  const [management,setManagement]=useState(undefined);","  const [management,setManagement]=useState(undefined);\n  const [entitlements,setEntitlements]=useState(null);\n  const [showOnboarding,setShowOnboarding]=useState(!user.onboardingCompleted);",1)
old="api('/api/management/overview').then(setManagement).catch(()=>setManagement({organization:null})); api('/api/admin/me').then(x=>setIsAdmin(Boolean(x.admin))).catch(()=>setIsAdmin(false)); const params=new URLSearchParams(window.location.search); const caseId=params.get('case'); if(caseId)setSelected(caseId);"
new="api('/api/management/overview').then(setManagement).catch(()=>setManagement({organization:null})); api('/api/entitlements').then(setEntitlements).catch(()=>setEntitlements({scope:'private',pro:false,usage:{activeCases:0},limits:{maxActiveCases:5,maxPhotosPerCase:3}})); api('/api/admin/me').then(x=>setIsAdmin(Boolean(x.admin))).catch(()=>setIsAdmin(false)); const params=new URLSearchParams(window.location.search); const caseId=params.get('case'); const requestedView=params.get('view'); if(caseId)setSelected(caseId); else if(requestedView)setView(requestedView);"
if old not in a:raise SystemExit('workspace effect missing')
a=a.replace(old,new,1)
go="  const goProfile = () => { setSelected(null); setView('profile'); };"
a=a.replace(go,go+"\n  const hasPro=Boolean(entitlements?.pro);\n  const selectView=(next,proOnly=false)=>{setSelected(null);if(proOnly&&!hasPro&&!management?.organization){setView('billing');return}setView(next)};\n  const finishOnboarding=(updated,useCase)=>{setUser(updated);setShowOnboarding(false);if(useCase==='management'){setSelected(null);setView('team')}};",1)
a=a.replace("<CaseDetail caseId={selected} onBack={() => setSelected(null)} onUpdated={loadCases} user={user} onProfile={goProfile} />","<CaseDetail caseId={selected} onBack={() => setSelected(null)} onUpdated={loadCases} user={user} onProfile={goProfile} pro={hasPro} onUpgrade={()=>setView('billing')} />",1)
for name in ['analytics','search','deadlines','inspections','calendar','tasks']:
 a=a.replace(f"onClick={{() => {{ setSelected(null); setView('{name}'); }}}}",f"onClick={{() => selectView('{name}',true)}}")
a=a.replace("{management?.organization?'Analyse':'Auswertung'}</button>","{management?.organization?'Analyse':'Auswertung'}{!management?.organization&&!hasPro&&<i className=\"proNavTag\">PRO</i>}</button>",1)
for text in ['Suche & Archiv','Übergabe / Abnahme','Kalender','Aufgaben']:
 a=a.replace(f'>{text}</button>',f'>{text}{{!management?.organization&&!hasPro&&<i className="proNavTag">PRO</i>}}</button>',1)
a=a.replace("<button onClick={() => navigate('/')}><span>↗</span>Startseite</button>","<button onClick={()=>setShowOnboarding(true)}><span>?</span>Einführung</button><button onClick={() => navigate('/')}><span>↗</span>Startseite</button>",1)
main='<main className="workspaceMain"><div className="mobileWorkspaceBar"><Logo compact /><button onClick={() => setShowNew(true)}>+ Neuer Mangel</button></div>{error && <div className="workspaceGlobalError">{error}</div>}{content}</main>'
main2='<main className="workspaceMain"><div className="mobileWorkspaceBar"><Logo compact /><button onClick={() => setShowNew(true)}>+ Neuer Mangel</button></div>{!management?.organization&&entitlements&&!hasPro&&<div className="freePlanTop"><span><b>Privat Free</b> {entitlements.usage?.activeCases||0} / 5 aktive Vorgänge · 3 Fotos je Vorgang</span><button onClick={()=>setView(\'billing\')}>Pro freischalten · 4,99 € →</button></div>}{error && <div className="workspaceGlobalError">{error}</div>}{content}</main>'
if main not in a:raise SystemExit('workspace main missing')
a=a.replace(main,main2,1)
a=a.replace("{showNew && <NewCase onClose={() => setShowNew(false)} onCreated={created => { setShowNew(false); loadCases(); setSelected(created.id); }} />}</div>;","{showNew && <NewCase pro={hasPro} entitlements={entitlements} onClose={() => setShowNew(false)} onCreated={created => { setShowNew(false); loadCases(); api('/api/entitlements').then(setEntitlements).catch(()=>{}); setSelected(created.id); }} />}{showOnboarding&&<OnboardingFlow user={user} onDone={finishOnboarding}/>}</div>;",1)
p.write_text(a)
print('v0.19 client prepared')
